// Group the 200 benchmark accounts into batches of 10 (Apollo bulk enrich takes up to 10).
// If started from the webhook with {"limit": N}, only N accounts are used (for a cheap test).
let limit = null;
try { limit = Number($('Run from outside (webhook)').first().json.body?.limit) || null; } catch (e) {}
let accts = $input.all().map(i => i.json);
if (limit) accts = accts.slice(0, limit);
const out = [];
for (let s = 0; s < accts.length; s += 10) {
  const chunk = accts.slice(s, s + 10);
  const qs = chunk.map(a => 'domains[]=' + encodeURIComponent(a.domain)).join('&');
  out.push({ json: { url: 'https://api.apollo.io/api/v1/organizations/bulk_enrich?' + qs,
                     accounts: chunk.map(a => ({ company_key: a.company_key, domain: a.domain })) } });
}
return out;

// Match each Apollo organization back to the account we asked about (by domain).
const host = u => String(u || '').toLowerCase().replace(/^https?:\/\//, '').replace(/^www\./, '').split('/')[0];
const batches = $('Make batches of 10').all();
const rows = [];
$input.all().forEach((item, idx) => {
  const b = batches[item.pairedItem?.item ?? idx].json;
  const orgs = (item.json.organizations || []).filter(Boolean);
  const byDomain = {};
  for (const o of orgs) { for (const d of [o.primary_domain, host(o.website_url)]) if (d) byDomain[host(d)] = o; }
  for (const a of b.accounts) {
    const o = byDomain[host(a.domain)];
    rows.push({
      run_label: 'apollo_baseline', company_key: a.company_key, provider: 'apollo',
      matched: !!o,
      employee_count: o?.estimated_num_employees ?? null,
      industry: o?.industry ?? null,
      linkedin_url: o?.linkedin_url ?? null,
      phone: o?.primary_phone?.number ?? o?.phone ?? o?.sanitized_phone ?? null,
      hq_country: o?.country ?? null,
      founded_year: o?.founded_year ?? null,
      credits_used: o ? 1 : 0,          // Apollo: 1 credit per organization returned, 0 for no match
      raw: o ? { id: o.id, name: o.name, primary_domain: o.primary_domain } : null,
      error: null,
    });
  }
});
return [{ json: { rows } }];

const rows = $('Read Apollo results').first().json.rows;
const n = rows.length, m = rows.filter(r => r.matched).length;
const pct = k => n ? Math.round(100 * rows.filter(r => r[k] != null).length / n) + '%' : '0%';
return [{ json: { accounts: n, matched: m, match_rate: n ? Math.round(100 * m / n) + '%' : '0%',
  size: pct('employee_count'), industry: pct('industry'), linkedin: pct('linkedin_url'), phone: pct('phone'),
  credits_used_estimate: rows.reduce((s, r) => s + r.credits_used, 0) } }];

const b = $('Make batches of 10').item.json;
return { json: { node: 'Apollo bulk enrich', provider: 'apollo',
  error: String($json.error?.message || $json.error || 'unknown').slice(0, 500),
  payload: { accounts: b.accounts } } };
